create table if not exists public.rto_sort_centers(id uuid primary key default gen_random_uuid(),hub_id uuid not null references public.hubs(id) on delete cascade,name text not null,to_email text not null,cc_email text,created_by uuid references public.profiles(id) on delete set null default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(hub_id,name),check(length(trim(name))>0),check(length(trim(to_email))>0));
alter table public.rto_sort_centers enable row level security;
create policy "rto_sort_centers_select" on public.rto_sort_centers for select to authenticated using(public.user_can_access_hub(hub_id));
create policy "rto_sort_centers_insert" on public.rto_sort_centers for insert to authenticated with check(public.user_role()='super_admin' or(public.user_role() in('hub_admin','supervisor') and public.user_can_access_hub(hub_id)));
create policy "rto_sort_centers_update" on public.rto_sort_centers for update to authenticated using(public.user_role()='super_admin' or(public.user_role() in('hub_admin','supervisor') and public.user_can_access_hub(hub_id))) with check(public.user_role()='super_admin' or(public.user_role() in('hub_admin','supervisor') and public.user_can_access_hub(hub_id)));
create policy "rto_sort_centers_delete" on public.rto_sort_centers for delete to authenticated using(public.user_role()='super_admin' or(public.user_role() in('hub_admin','supervisor') and public.user_can_access_hub(hub_id)));
create index if not exists rto_sort_centers_hub_idx on public.rto_sort_centers(hub_id);
